     1	//! Vault: a tiny multi-user document store with a request-handler layer.
     2	//!
     3	//! The layers, bottom to top:
     4	//!
     5	//! - `users`, `auth`: who the callers are and how they prove it.
     6	//! - `store`, `quota`, `audit`: the documents, what each user may keep, and what happened.
     7	//! - `query`: a small filter language evaluated over the documents.
     8	//! - `files`, `export`: attachments on disk, and documents rendered to text, Markdown or JSON.
     9	//! - `service`: the rules (who may read, change or delete what) on top of the storage.
    10	//! - `wire`, `handler`: the binary frames and the text commands a front end sends.
    11	//!
    12	//! The digests used for passwords and tokens are small stand-ins for real ones, so the crate
    13	//! needs no dependencies; their strength is not what this crate is about.
    14	
    15	pub mod audit;
    16	pub mod auth;
    17	pub mod error;
    18	pub mod export;
    19	pub mod files;
    20	pub mod handler;
    21	pub mod query;
    22	pub mod quota;
    23	pub mod service;
    24	pub mod store;
    25	pub mod text;
    26	pub mod users;
    27	pub mod wire;
    28	
    29	pub use error::{Result, VaultError};
===== src/error.rs =====
     1	//! The error type shared by every layer, and the status code each kind maps to.
     2	
     3	use std::fmt;
     4	
     5	/// Everything that can go wrong while serving a request.
     6	#[derive(Debug, Clone, PartialEq, Eq)]
     7	pub enum VaultError {
     8	    /// The thing asked for does not exist.
     9	    NotFound(String),
    10	    /// The caller is known but may not do this.
    11	    Denied(String),
    12	    /// The caller is not logged in, or the credentials are wrong.
    13	    Unauthenticated(String),
    14	    /// The input is well-formed but not acceptable.
    15	    Invalid(String),
    16	    /// The input is not well-formed at all.
    17	    Malformed(String),
    18	    /// A per-user limit was reached.
    19	    QuotaExceeded(String),
    20	    /// The disk said no.
    21	    Io(String),
    22	}
    23	
    24	/// The result type of the whole crate.
    25	pub type Result<T> = std::result::Result<T, VaultError>;
    26	
    27	impl VaultError {
    28	    /// The status code a front end should answer with.
    29	    pub fn status(&self) -> u16 {
    30	        match self {
    31	            VaultError::NotFound(_) => 404,
    32	            VaultError::Denied(_) => 403,
    33	            VaultError::Unauthenticated(_) => 401,
    34	            VaultError::Invalid(_) | VaultError::Malformed(_) => 400,
    35	            VaultError::QuotaExceeded(_) => 413,
    36	            VaultError::Io(_) => 500,
    37	        }
    38	    }
    39	
    40	    /// The human-readable part of the error.
    41	    pub fn message(&self) -> &str {
    42	        match self {
    43	            VaultError::NotFound(m)
    44	            | VaultError::Denied(m)
    45	            | VaultError::Unauthenticated(m)
    46	            | VaultError::Invalid(m)
    47	            | VaultError::Malformed(m)
    48	            | VaultError::QuotaExceeded(m)
    49	            | VaultError::Io(m) => m,
    50	        }
    51	    }
    52	}
    53	
    54	impl fmt::Display for VaultError {
    55	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
    56	        let kind = match self {
    57	            VaultError::NotFound(_) => "not found",
    58	            VaultError::Denied(_) => "denied",
    59	            VaultError::Unauthenticated(_) => "unauthenticated",
    60	            VaultError::Invalid(_) => "invalid",
    61	            VaultError::Malformed(_) => "malformed",
    62	            VaultError::QuotaExceeded(_) => "quota exceeded",
    63	            VaultError::Io(_) => "i/o error",
    64	        };
    65	        write!(f, "{kind}: {}", self.message())
    66	    }
    67	}
    68	
    69	impl std::error::Error for VaultError {}
    70	
    71	impl From<std::io::Error> for VaultError {
    72	    fn from(e: std::io::Error) -> Self {
    73	        if e.kind() == std::io::ErrorKind::NotFound {
    74	            VaultError::NotFound(e.to_string())
    75	        } else {
    76	            VaultError::Io(e.to_string())
    77	        }
    78	    }
    79	}
===== src/auth.rs =====
     1	//! Passwords and tokens.
     2	//!
     3	//! A token is `ID.MAC`, where the MAC is a keyed digest of the id under the server secret. The
     4	//! digest is a 64-bit FNV-1a: a stand-in that keeps the crate free of dependencies.
     5	
     6	use crate::error::{Result, VaultError};
     7	use crate::users::{Directory, UserId};
     8	
     9	const FNV_OFFSET: u64 = 0xcbf2_9ce4_8422_2325;
    10	const FNV_PRIME: u64 = 0x0000_0100_0000_01b3;
    11	
    12	/// A digest of `parts`, each followed by a separator so `["ab", "c"]` and `["a", "bc"]` differ.
    13	pub fn digest(parts: &[&str]) -> u64 {
    14	    let mut h = FNV_OFFSET;
    15	    for part in parts {
    16	        for b in part.bytes().chain(std::iter::once(0xff)) {
    17	            h ^= u64::from(b);
    18	            h = h.wrapping_mul(FNV_PRIME);
    19	        }
    20	    }
    21	    h
    22	}
    23	
    24	/// The stored form of a password.
    25	pub fn hash_password(salt: &str, password: &str) -> u64 {
    26	    digest(&[salt, password])
    27	}
    28	
    29	/// The MAC part of the token of user `id`, as 16 hex digits.
    30	pub fn token_mac(secret: &str, id: UserId) -> String {
    31	    format!("{:016x}", digest(&[secret, &id.to_string()]))
    32	}
    33	
    34	/// The token a user presents with every request.
    35	pub fn issue_token(secret: &str, id: UserId) -> String {
    36	    format!("{id}.{}", token_mac(secret, id))
    37	}
    38	
    39	/// Whether two secrets are equal, taking the same time wherever they differ.
    40	pub fn tokens_match(a: &str, b: &str) -> bool {
    41	    let (a, b) = (a.as_bytes(), b.as_bytes());
    42	    if a.len() != b.len() {
    43	        return false;
    44	    }
    45	    let mut diff = 0u8;
    46	    for (x, y) in a.iter().zip(b) {
    47	        diff |= x ^ y;
    48	    }
    49	    diff == 0
    50	}
    51	
    52	/// The user a token belongs to, or why it is no good.
    53	pub fn verify_token(dir: &Directory, secret: &str, token: &str) -> Result<UserId> {
    54	    let bad = || VaultError::Unauthenticated("invalid token".into());
    55	    let (id, mac) = token.split_once('.').ok_or_else(bad)?;
    56	    let id: UserId = id.parse().map_err(|_| bad())?;
    57	    dir.get(id).ok_or_else(bad)?;
    58	    if tokens_match(&token_mac(secret, id), mac) {
    59	        Ok(id)
    60	    } else {
    61	        Err(bad())
    62	    }
    63	}
    64	
    65	/// Checks a name and password and returns a token. An unknown name and a wrong password give the
    66	/// same error, so a caller cannot tell which accounts exist.
    67	pub fn login(dir: &Directory, secret: &str, name: &str, password: &str) -> Result<String> {
    68	    let bad = || VaultError::Unauthenticated("wrong name or password".into());
    69	    let user = dir.by_name(name).ok_or_else(bad)?;
    70	    let given = format!("{:016x}", hash_password(&user.salt, password));
    71	    let stored = format!("{:016x}", user.password_hash);
    72	    if tokens_match(&given, &stored) {
    73	        Ok(issue_token(secret, user.id))
    74	    } else {
    75	        Err(bad())
    76	    }
    77	}
