     1	//! Users, their roles and the directory that looks them up.
     2	
     3	use crate::auth::hash_password;
     4	use crate::error::{Result, VaultError};
     5	use crate::text::is_valid_username;
     6	
     7	/// The id of a user; ids start at 1 and are never reused.
     8	pub type UserId = u32;
     9	
    10	/// What a user may do. The order matters: a higher role can do everything a lower one can.
    11	#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
    12	pub enum Role {
    13	    /// Reads what is shared with them, writes nothing.
    14	    Guest,
    15	    /// Keeps documents of their own.
    16	    Member,
    17	    /// Manages everybody's documents.
    18	    Admin,
    19	}
    20	
    21	impl Role {
    22	    /// The role named `s`, if any.
    23	    pub fn parse(s: &str) -> Option<Role> {
    24	        match s.trim().to_ascii_lowercase().as_str() {
    25	            "guest" => Some(Role::Guest),
    26	            "member" => Some(Role::Member),
    27	            "admin" => Some(Role::Admin),
    28	            _ => None,
    29	        }
    30	    }
    31	
    32	    /// The name `parse` reads back.
    33	    pub fn name(self) -> &'static str {
    34	        match self {
    35	            Role::Guest => "guest",
    36	            Role::Member => "member",
    37	            Role::Admin => "admin",
    38	        }
    39	    }
    40	
    41	    /// Whether the role may create and change documents.
    42	    pub fn can_write(self) -> bool {
    43	        self >= Role::Member
    44	    }
    45	}
    46	
    47	/// One account.
    48	#[derive(Debug, Clone, PartialEq, Eq)]
    49	pub struct User {
    50	    pub id: UserId,
    51	    pub name: String,
    52	    pub role: Role,
    53	    pub salt: String,
    54	    pub password_hash: u64,
    55	}
    56	
    57	/// All the accounts, looked up by id or by name.
    58	#[derive(Debug)]
    59	pub struct Directory {
    60	    users: Vec<User>,
    61	    next: UserId,
    62	}
    63	
    64	impl Default for Directory {
    65	    fn default() -> Self {
    66	        Directory::new()
    67	    }
    68	}
    69	
    70	impl Directory {
    71	    /// An empty directory.
    72	    pub fn new() -> Directory {
    73	        Directory { users: Vec::new(), next: 1 }
    74	    }
    75	
    76	    /// Adds an account. Names are unique ignoring case; passwords need 8 characters.
    77	    pub fn add(&mut self, name: &str, role: Role, password: &str) -> Result<UserId> {
    78	        if !is_valid_username(name) {
    79	            return Err(VaultError::Invalid(format!("bad user name {name:?}")));
    80	        }
    81	        if password.chars().count() < 8 {
    82	            return Err(VaultError::Invalid("the password needs at least 8 characters".into()));
    83	        }
    84	        if self.by_name(name).is_some() {
    85	            return Err(VaultError::Invalid(format!("the name {name} is taken")));
    86	        }
    87	        let id = self.next;
    88	        self.next += 1;
    89	        let salt = format!("vault:{id}:{}", name.to_ascii_lowercase());
    90	        let password_hash = hash_password(&salt, password);
    91	        self.users.push(User { id, name: name.to_string(), role, salt, password_hash });
    92	        Ok(id)
    93	    }
    94	
    95	    /// The account with this id.
    96	    pub fn get(&self, id: UserId) -> Option<&User> {
    97	        self.users.iter().find(|u| u.id == id)
    98	    }
    99	
   100	    /// The account with this name, ignoring case.
   101	    pub fn by_name(&self, name: &str) -> Option<&User> {
   102	        self.users.iter().find(|u| u.name.eq_ignore_ascii_case(name))
   103	    }
   104	
   105	    /// The role of a user, if the user exists.
   106	    pub fn role_of(&self, id: UserId) -> Option<Role> {
   107	        self.get(id).map(|u| u.role)
   108	    }
   109	
   110	    /// Whether the user exists and is an admin.
   111	    pub fn is_admin(&self, id: UserId) -> bool {
   112	        self.role_of(id) == Some(Role::Admin)
   113	    }
   114	
   115	    /// Changes a user's role. The last admin cannot be demoted.
   116	    pub fn set_role(&mut self, id: UserId, role: Role) -> Result<()> {
   117	        let admins = self.users.iter().filter(|u| u.role == Role::Admin).count();
   118	        let user =
   119	            self.users.iter_mut().find(|u| u.id == id).ok_or_else(|| VaultError::NotFound(format!("user {id}")))?;
   120	        if user.role == Role::Admin && role != Role::Admin && admins == 1 {
   121	            return Err(VaultError::Invalid("the last admin cannot be demoted".into()));
   122	        }
   123	        user.role = role;
   124	        Ok(())
   125	    }
   126	
   127	    /// How many accounts there are.
   128	    pub fn len(&self) -> usize {
   129	        self.users.len()
   130	    }
   131	
   132	    /// Whether there are no accounts.
   133	    pub fn is_empty(&self) -> bool {
   134	        self.users.is_empty()
   135	    }
   136	
   137	    /// The names of all accounts, in creation order.
   138	    pub fn names(&self) -> Vec<&str> {
   139	        self.users.iter().map(|u| u.name.as_str()).collect()
   140	    }
   141	}
===== src/store.rs =====
     1	//! The documents. This layer only keeps them: who may see or change what is decided one level up,
     2	//! in `service`.
     3	
     4	use std::collections::BTreeMap;
     5	
     6	use crate::users::UserId;
     7	
     8	/// The id of a document; ids start at 1 and are never reused.
     9	pub type DocId = u64;
    10	
    11	/// One stored document.
    12	#[derive(Debug, Clone, PartialEq, Eq)]
    13	pub struct Document {
    14	    pub id: DocId,
    15	    pub owner: UserId,
    16	    pub title: String,
    17	    pub body: String,
    18	    pub tags: Vec<String>,
    19	    pub created: u64,
    20	    pub modified: u64,
    21	}
    22	
    23	impl Document {
    24	    /// The size of the body in bytes.
    25	    pub fn size(&self) -> usize {
    26	        self.body.len()
    27	    }
    28	
    29	    /// Whether the document carries this tag.
    30	    pub fn has_tag(&self, tag: &str) -> bool {
    31	        self.tags.iter().any(|t| t == tag)
    32	    }
    33	}
    34	
    35	/// All the documents, ordered by id.
    36	#[derive(Debug)]
    37	pub struct Store {
    38	    docs: BTreeMap<DocId, Document>,
    39	    next: DocId,
    40	}
    41	
    42	impl Default for Store {
    43	    fn default() -> Self {
    44	        Store::new()
    45	    }
    46	}
    47	
    48	impl Store {
    49	    /// An empty store.
    50	    pub fn new() -> Store {
    51	        Store { docs: BTreeMap::new(), next: 1 }
    52	    }
    53	
    54	    /// Keeps a new document and returns its id.
    55	    pub fn insert(&mut self, owner: UserId, title: &str, body: &str, tags: Vec<String>, now: u64) -> DocId {
    56	        let id = self.next;
    57	        self.next += 1;
    58	        let doc =
    59	            Document { id, owner, title: title.to_string(), body: body.to_string(), tags, created: now, modified: now };
    60	        self.docs.insert(id, doc);
    61	        id
    62	    }
    63	
    64	    /// The document with this id.
    65	    pub fn get(&self, id: DocId) -> Option<&Document> {
    66	        self.docs.get(&id)
    67	    }
    68	
    69	    /// Replaces a body and returns the old size, or `None` when there is no such document.
    70	    pub fn set_body(&mut self, id: DocId, body: &str, now: u64) -> Option<usize> {
    71	        let doc = self.docs.get_mut(&id)?;
    72	        let old = doc.body.len();
    73	        doc.body = body.to_string();
    74	        doc.modified = now;
    75	        Some(old)
    76	    }
    77	
    78	    /// Takes a document out of the store.
    79	    pub fn remove(&mut self, id: DocId) -> Option<Document> {
    80	        self.docs.remove(&id)
    81	    }
    82	
    83	    /// How many documents there are.
    84	    pub fn len(&self) -> usize {
    85	        self.docs.len()
    86	    }
    87	
    88	    /// Whether there are no documents.
    89	    pub fn is_empty(&self) -> bool {
    90	        self.docs.is_empty()
    91	    }
    92	
    93	    /// Every document, in id order.
    94	    pub fn iter(&self) -> impl Iterator<Item = &Document> {
    95	        self.docs.values()
    96	    }
    97	
    98	    /// The documents of one owner, in id order.
    99	    pub fn by_owner(&self, owner: UserId) -> Vec<&Document> {
   100	        self.iter().filter(|d| d.owner == owner).collect()
   101	    }
   102	
   103	    /// The bytes of body text one owner keeps.
   104	    pub fn bytes_of(&self, owner: UserId) -> usize {
   105	        self.by_owner(owner).iter().map(|d| d.size()).sum()
   106	    }
   107	}

===== src/service.rs =====
     1	//! The rules: who may create, read, change and delete which document, on top of the storage.
     2	//!
     3	//! A document belongs to its owner. Admins may do everything with every document; guests may not
     4	//! write at all.
     5	
     6	use crate::audit::AuditLog;
     7	use crate::error::{Result, VaultError};
     8	use crate::query;
     9	use crate::quota::Quota;
    10	use crate::store::{DocId, Document, Store};
    11	use crate::users::{Directory, Role, UserId};
    12	
    13	/// The longest title, in characters.
    14	pub const MAX_TITLE: usize = 120;
    15	
    16	/// The largest body, in bytes.
    17	pub const MAX_BODY: usize = 64 * 1024;
    18	
    19	/// The whole application state.
    20	#[derive(Debug)]
    21	pub struct Service {
    22	    pub users: Directory,
    23	    pub store: Store,
    24	    pub quota: Quota,
    25	    pub audit: AuditLog,
    26	    clock: u64,
    27	}
    28	
    29	impl Service {
    30	    /// An empty service where each user may keep `quota_bytes` of body text.
    31	    pub fn new(quota_bytes: usize) -> Service {
    32	        Service {
    33	            users: Directory::new(),
    34	            store: Store::new(),
    35	            quota: Quota::new(quota_bytes),
    36	            audit: AuditLog::new(500),
    37	            clock: 0,
    38	        }
    39	    }
    40	
    41	    fn tick(&mut self) -> u64 {
    42	        self.clock += 1;
    43	        self.clock
    44	    }
    45	
    46	    /// Adds an account.
    47	    pub fn register(&mut self, name: &str, role: Role, password: &str) -> Result<UserId> {
    48	        let id = self.users.add(name, role, password)?;
    49	        self.audit.record(id, "register", &id.to_string());
    50	        Ok(id)
    51	    }
    52	
    53	    fn require_writer(&self, user: UserId) -> Result<()> {
    54	        match self.users.role_of(user) {
    55	            Some(role) if role.can_write() => Ok(()),
    56	            Some(_) => Err(VaultError::Denied("guests cannot write".into())),
    57	            None => Err(VaultError::Unauthenticated(format!("no user {user}"))),
    58	        }
    59	    }
    60	
    61	    /// Whether `user` may see and change `doc`: the owner and the admins may.
    62	    pub fn can_access(&self, user: UserId, doc: &Document) -> bool {
    63	        doc.owner == user || self.users.is_admin(user)
    64	    }
    65	
    66	    fn not_found(id: DocId) -> VaultError {
    67	        VaultError::NotFound(format!("document {id}"))
    68	    }
    69	
    70	    /// Keeps a new document for `user`.
    71	    pub fn create(&mut self, user: UserId, title: &str, body: &str, tags: Vec<String>) -> Result<DocId> {
    72	        self.require_writer(user)?;
    73	        let title = title.trim();
    74	        if title.is_empty() || title.chars().count() > MAX_TITLE {
    75	            return Err(VaultError::Invalid(format!("a title has 1 to {MAX_TITLE} characters")));
    76	        }
    77	        if body.len() > MAX_BODY {
    78	            return Err(VaultError::Invalid(format!("a body has at most {MAX_BODY} bytes")));
    79	        }
    80	        self.quota.charge(user, body.len())?;
    81	        let now = self.tick();
    82	        let id = self.store.insert(user, title, body, tags, now);
    83	        self.audit.record(user, "create", &id.to_string());
    84	        Ok(id)
    85	    }
    86	
    87	    /// A document `user` may read.
    88	    pub fn fetch(&self, user: UserId, id: DocId) -> Result<&Document> {
    89	        let doc = self.store.get(id).ok_or_else(|| Self::not_found(id))?;
    90	        if !self.can_access(user, doc) {
    91	            return Err(VaultError::Denied(format!("document {id} belongs to someone else")));
    92	        }
    93	        Ok(doc)
    94	    }
    95	
    96	    /// Replaces the body of a document `user` may change.
    97	    pub fn update(&mut self, user: UserId, id: DocId, body: &str) -> Result<()> {
    98	        self.require_writer(user)?;
    99	        let doc = self.store.get(id).ok_or_else(|| Self::not_found(id))?;
   100	        if !self.can_access(user, doc) {
   101	            return Err(VaultError::Denied(format!("document {id} belongs to someone else")));
   102	        }
   103	        if body.len() > MAX_BODY {
   104	            return Err(VaultError::Invalid(format!("a body has at most {MAX_BODY} bytes")));
   105	        }
   106	        let owner = doc.owner;
   107	        let old = doc.size();
   108	        if body.len() >= old {
   109	            self.quota.charge(owner, body.len() - old)?;
   110	        } else {
   111	            self.quota.release(owner, old - body.len());
   112	        }
   113	        let now = self.tick();
   114	        self.store.set_body(id, body, now);
   115	        self.audit.record(user, "update", &id.to_string());
   116	        Ok(())
   117	    }
   118	
   119	    /// Removes a document and gives its bytes back to the owner's quota.
   120	    pub fn delete(&mut self, user: UserId, id: DocId) -> Result<Document> {
   121	        self.require_writer(user)?;
   122	        let doc = self.store.remove(id).ok_or_else(|| Self::not_found(id))?;
   123	        self.quota.release(doc.owner, doc.size());
   124	        self.audit.record(user, "delete", &id.to_string());
   125	        Ok(doc)
   126	    }
   127	
   128	    /// The documents `user` owns; an admin gets every document.
   129	    pub fn list(&self, user: UserId) -> Vec<&Document> {
   130	        if self.users.is_admin(user) {
   131	            self.store.iter().collect()
   132	        } else {
   133	            self.store.by_owner(user)
   134	        }
   135	    }
   136	
   137	    /// The documents of `user` whose title contains `term`.
   138	    pub fn search(&self, user: UserId, term: &str) -> Result<Vec<&Document>> {
   139	        let ids = query::search(&self.store, user, term)?;
   140	        Ok(ids.into_iter().filter_map(|id| self.store.get(id)).collect())
   141	    }
