     1	//! How much body text each user may keep.
     2	
     3	use std::collections::BTreeMap;
     4	
     5	use crate::error::{Result, VaultError};
     6	use crate::users::UserId;
     7	
     8	/// A byte budget per user.
     9	#[derive(Debug)]
    10	pub struct Quota {
    11	    limit: usize,
    12	    used: BTreeMap<UserId, usize>,
    13	}
    14	
    15	impl Quota {
    16	    /// Every user may keep `limit` bytes.
    17	    pub fn new(limit: usize) -> Quota {
    18	        Quota { limit, used: BTreeMap::new() }
    19	    }
    20	
    21	    /// The budget of one user.
    22	    pub fn limit(&self) -> usize {
    23	        self.limit
    24	    }
    25	
    26	    /// The bytes a user has used.
    27	    pub fn used(&self, user: UserId) -> usize {
    28	        self.used.get(&user).copied().unwrap_or(0)
    29	    }
    30	
    31	    /// The bytes a user may still add.
    32	    pub fn remaining(&self, user: UserId) -> usize {
    33	        self.limit.saturating_sub(self.used(user))
    34	    }
    35	
    36	    /// Uses `bytes` of the budget, or fails and changes nothing.
    37	    pub fn charge(&mut self, user: UserId, bytes: usize) -> Result<()> {
    38	        let total = self.used(user).checked_add(bytes).filter(|t| *t <= self.limit);
    39	        match total {
    40	            Some(t) => {
    41	                self.used.insert(user, t);
    42	                Ok(())
    43	            }
    44	            None => Err(VaultError::QuotaExceeded(format!("user {user} would pass {} bytes", self.limit))),
    45	        }
    46	    }
    47	
    48	    /// Gives `bytes` back (never below zero).
    49	    pub fn release(&mut self, user: UserId, bytes: usize) {
    50	        let left = self.used(user).saturating_sub(bytes);
    51	        self.used.insert(user, left);
    52	    }
    53	}
