     1	//! Small text helpers shared by the layers: names, tags and display escaping.
     2	
     3	/// The longest name `sanitize_name` returns.
     4	pub const MAX_NAME: usize = 48;
     5	
     6	/// The most tags one document keeps.
     7	pub const MAX_TAGS: usize = 8;
     8	
     9	/// Lower-cases `raw` and keeps only ASCII letters and digits; every other run of characters becomes
    10	/// one `-`. The result never starts or ends with `-`, has at most `MAX_NAME` characters and is
    11	/// never empty (`untitled` stands in).
    12	pub fn sanitize_name(raw: &str) -> String {
    13	    let mut out = String::new();
    14	    let mut gap = false;
    15	    for c in raw.chars() {
    16	        if c.is_ascii_alphanumeric() {
    17	            if gap && !out.is_empty() {
    18	                out.push('-');
    19	            }
    20	            gap = false;
    21	            out.push(c.to_ascii_lowercase());
    22	        } else {
    23	            gap = true;
    24	        }
    25	    }
    26	    out.truncate(MAX_NAME);
    27	    while out.ends_with('-') {
    28	        out.pop();
    29	    }
    30	    if out.is_empty() {
    31	        "untitled".to_string()
    32	    } else {
    33	        out
    34	    }
    35	}
    36	
    37	/// Whether `name` can be a login: 3 to 24 letters, digits or underscores.
    38	pub fn is_valid_username(name: &str) -> bool {
    39	    (3..=24).contains(&name.len()) && name.chars().all(|c| c.is_ascii_alphanumeric() || c == '_')
    40	}
    41	
    42	/// At most `max` characters of `s`; a cut ends in `...`.
    43	pub fn truncate(s: &str, max: usize) -> String {
    44	    if s.chars().count() <= max {
    45	        return s.to_string();
    46	    }
    47	    let keep: String = s.chars().take(max.saturating_sub(3)).collect();
    48	    format!("{keep}...")
    49	}
    50	
    51	/// `s` made safe to put in an HTML page.
    52	pub fn escape_display(s: &str) -> String {
    53	    let mut out = String::with_capacity(s.len());
    54	    for c in s.chars() {
    55	        match c {
    56	            '&' => out.push_str("&amp;"),
    57	            '<' => out.push_str("&lt;"),
    58	            '>' => out.push_str("&gt;"),
    59	            '"' => out.push_str("&quot;"),
    60	            '\'' => out.push_str("&#39;"),
    61	            c => out.push(c),
    62	        }
    63	    }
    64	    out
    65	}
    66	
    67	/// The tags in a comma-separated list: sanitized, without duplicates, at most `MAX_TAGS`.
    68	pub fn parse_tags(raw: &str) -> Vec<String> {
    69	    let mut tags: Vec<String> = Vec::new();
    70	    for part in raw.split(',').map(str::trim).filter(|p| !p.is_empty()) {
    71	        let tag = sanitize_name(part);
    72	        if !tags.contains(&tag) && tags.len() < MAX_TAGS {
    73	            tags.push(tag);
    74	        }
    75	    }
    76	    tags
    77	}
    78	
    79	/// The `|`-separated fields of `s`, trimmed; at most `n`, the last one keeps any further `|`.
    80	/// Missing fields come back empty, so the result always has exactly `n` entries.
    81	pub fn split_fields(s: &str, n: usize) -> Vec<&str> {
    82	    let mut fields: Vec<&str> = s.splitn(n, '|').map(str::trim).collect();
    83	    fields.resize(n, "");
    84	    fields
    85	}
    86	
    87	/// Whether `s` holds a control character (a line break, say).
    88	pub fn has_control(s: &str) -> bool {
    89	    s.chars().any(char::is_control)
    90	}

