     1	//! The filter language: a small query evaluated over the documents.
     2	//!
     3	//! ```text
     4	//! filter := clause ("OR" clause)*
     5	//! clause := cond ("AND" cond)*
     6	//! cond   := field op value
     7	//! field  := owner | title | body | tag | size
     8	//! op     := = | != | ~ | < | >
     9	//! value  := a whole number, or "text" in double quotes
    10	//! ```
    11	//!
    12	//! `AND` binds tighter than `OR`. Text has no escapes: the next double quote ends it. `~` means
    13	//! "contains", ignoring case; `<` and `>` compare numbers only.
    14	
    15	use crate::error::{Result, VaultError};
    16	use crate::store::{DocId, Document, Store};
    17	use crate::users::UserId;
    18	
    19	/// The longest search term accepted.
    20	pub const MAX_TERM: usize = 64;
    21	
    22	/// What a condition looks at.
    23	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
    24	pub enum Field {
    25	    Owner,
    26	    Title,
    27	    Body,
    28	    Tag,
    29	    Size,
    30	}
    31	
    32	/// How a condition compares.
    33	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
    34	pub enum CmpOp {
    35	    Eq,
    36	    Ne,
    37	    Contains,
    38	    Lt,
    39	    Gt,
    40	}
    41	
    42	/// The right-hand side of a condition.
    43	#[derive(Debug, Clone, PartialEq, Eq)]
    44	pub enum Value {
    45	    Num(i64),
    46	    Text(String),
    47	}
    48	
    49	/// One `field op value` test.
    50	#[derive(Debug, Clone, PartialEq, Eq)]
    51	pub struct Cond {
    52	    pub field: Field,
    53	    pub op: CmpOp,
    54	    pub value: Value,
    55	}
    56	
    57	#[derive(Debug, Clone, PartialEq, Eq)]
    58	enum Token {
    59	    Word(String),
    60	    Text(String),
    61	    Number(i64),
    62	    Op(CmpOp),
    63	}
    64	
    65	fn tokenize(src: &str) -> Result<Vec<Token>> {
    66	    let mut out = Vec::new();
    67	    let mut chars = src.chars().peekable();
    68	    while let Some(&c) = chars.peek() {
    69	        if c.is_whitespace() {
    70	            chars.next();
    71	        } else if c == '"' {
    72	            chars.next();
    73	            let mut text = String::new();
    74	            loop {
    75	                match chars.next() {
    76	                    Some('"') => break,
    77	                    Some(ch) => text.push(ch),
    78	                    None => return Err(VaultError::Malformed("unterminated text in the filter".into())),
    79	                }
    80	            }
    81	            out.push(Token::Text(text));
    82	        } else if c.is_ascii_digit() || c == '-' {
    83	            let mut digits = String::new();
    84	            digits.push(c);
    85	            chars.next();
    86	            while let Some(&d) = chars.peek() {
    87	                if !d.is_ascii_digit() {
    88	                    break;
    89	                }
    90	                digits.push(d);
    91	                chars.next();
    92	            }
    93	            let n =
    94	                digits.parse().map_err(|_| VaultError::Malformed(format!("bad number {digits:?} in the filter")))?;
    95	            out.push(Token::Number(n));
    96	        } else if c.is_ascii_alphabetic() {
    97	            let mut word = String::new();
    98	            while let Some(&w) = chars.peek() {
    99	                if !w.is_ascii_alphanumeric() {
   100	                    break;
   101	                }
   102	                word.push(w);
   103	                chars.next();
   104	            }
   105	            out.push(Token::Word(word));
   106	        } else {
   107	            chars.next();
   108	            let op = match c {
   109	                '=' => CmpOp::Eq,
   110	                '~' => CmpOp::Contains,
   111	                '<' => CmpOp::Lt,
   112	                '>' => CmpOp::Gt,
   113	                '!' if chars.next() == Some('=') => CmpOp::Ne,
   114	                other => return Err(VaultError::Malformed(format!("unexpected {other:?} in the filter"))),
   115	            };
   116	            out.push(Token::Op(op));
   117	        }
   118	    }
   119	    Ok(out)
   120	}
   121	
   122	impl Field {
   123	    fn from_word(w: &str) -> Result<Field> {
   124	        match w.to_ascii_lowercase().as_str() {
   125	            "owner" => Ok(Field::Owner),
   126	            "title" => Ok(Field::Title),
   127	            "body" => Ok(Field::Body),
   128	            "tag" => Ok(Field::Tag),
   129	            "size" => Ok(Field::Size),
   130	            _ => Err(VaultError::Malformed(format!("unknown field {w:?}"))),
   131	        }
   132	    }
   133	
   134	    fn is_number(self) -> bool {
   135	        matches!(self, Field::Owner | Field::Size)
   136	    }
   137	}
   138	
   139	fn parse_cond(tokens: &[Token], at: &mut usize) -> Result<Cond> {
   140	    let mut next = || {
   141	        let t = tokens.get(*at).cloned().ok_or_else(|| VaultError::Malformed("the filter ends too early".into()));
   142	        *at += 1;
   143	        t
   144	    };
   145	    let field = match next()? {
   146	        Token::Word(w) => Field::from_word(&w)?,
   147	        other => return Err(VaultError::Malformed(format!("expected a field, found {other:?}"))),
   148	    };
   149	    let op = match next()? {
   150	        Token::Op(op) => op,
   151	        other => return Err(VaultError::Malformed(format!("expected an operator, found {other:?}"))),
   152	    };
   153	    let value = match next()? {
   154	        Token::Number(n) => Value::Num(n),
   155	        Token::Text(s) => Value::Text(s),
   156	        other => return Err(VaultError::Malformed(format!("expected a value, found {other:?}"))),
   157	    };
   158	    let numeric = matches!(value, Value::Num(_));
   159	    if numeric != field.is_number() {
   160	        return Err(VaultError::Invalid(format!("{field:?} does not compare with {value:?}")));
   161	    }
   162	    if matches!(op, CmpOp::Lt | CmpOp::Gt) && !numeric || op == CmpOp::Contains && numeric {
   163	        return Err(VaultError::Invalid(format!("{op:?} does not fit {value:?}")));
   164	    }
   165	    Ok(Cond { field, op, value })
   166	}
   167	
   168	impl Cond {
   169	    /// Whether the document satisfies this condition.
   170	    pub fn matches(&self, doc: &Document) -> bool {
   171	        match (&self.value, self.field) {
   172	            (Value::Num(n), Field::Owner) => compare(i64::from(doc.owner), self.op, *n),
   173	            (Value::Num(n), _) => compare(doc.size() as i64, self.op, *n),
   174	            (Value::Text(t), Field::Title) => text_matches(&doc.title, self.op, t),
   175	            (Value::Text(t), Field::Body) => text_matches(&doc.body, self.op, t),
   176	            (Value::Text(t), _) => {
   177	                let hit = doc
   178	                    .tags
   179	                    .iter()
   180	                    .any(|tag| text_matches(tag, if self.op == CmpOp::Ne { CmpOp::Eq } else { self.op }, t));
   181	                hit != (self.op == CmpOp::Ne)
   182	            }
   183	        }
   184	    }
   185	}
   186	
   187	fn compare(have: i64, op: CmpOp, want: i64) -> bool {
   188	    match op {
   189	        CmpOp::Eq => have == want,
   190	        CmpOp::Ne => have != want,
   191	        CmpOp::Lt => have < want,
   192	        CmpOp::Gt => have > want,
   193	        CmpOp::Contains => false,
   194	    }
   195	}
   196	
   197	fn text_matches(have: &str, op: CmpOp, want: &str) -> bool {
   198	    let (have, want) = (have.to_lowercase(), want.to_lowercase());
   199	    match op {
   200	        CmpOp::Eq => have == want,
   201	        CmpOp::Ne => have != want,
   202	        CmpOp::Contains => have.contains(&want),
   203	        CmpOp::Lt | CmpOp::Gt => false,
   204	    }
   205	}
   206	
   207	/// A parsed filter: alternatives of conditions that must all hold.
   208	#[derive(Debug, Clone, PartialEq, Eq)]
   209	pub struct Filter {
   210	    clauses: Vec<Vec<Cond>>,
   211	}
   212	
   213	impl Filter {
   214	    /// Whether the document satisfies at least one clause.
   215	    pub fn matches(&self, doc: &Document) -> bool {
   216	        self.clauses.iter().any(|clause| clause.iter().all(|c| c.matches(doc)))
   217	    }
   218	
   219	    /// How many `OR`-separated clauses the filter has.
   220	    pub fn clause_count(&self) -> usize {
   221	        self.clauses.len()
   222	    }
   223	}
   224	
   225	/// Parses a filter.
   226	pub fn parse(src: &str) -> Result<Filter> {
   227	    let tokens = tokenize(src)?;
   228	    let mut clauses = vec![Vec::new()];
   229	    let mut at = 0;
   230	    loop {
   231	        let cond = parse_cond(&tokens, &mut at)?;
   232	        clauses.last_mut().expect("one clause at least").push(cond);
   233	        match tokens.get(at) {
   234	            None => break,
   235	            Some(Token::Word(w)) if w.eq_ignore_ascii_case("and") => at += 1,
   236	            Some(Token::Word(w)) if w.eq_ignore_ascii_case("or") => {
   237	                at += 1;
   238	                clauses.push(Vec::new());
   239	            }
   240	            Some(other) => return Err(VaultError::Malformed(format!("expected AND or OR, found {other:?}"))),
   241	        }
   242	    }
   243	    Ok(Filter { clauses })
   244	}
   245	
   246	/// The filter that finds the documents of `owner` whose title contains `term`.
   247	pub fn search_filter(owner: UserId, term: &str) -> Result<String> {
   248	    let term = term.trim();
   249	    if term.is_empty() {
   250	        return Err(VaultError::Invalid("the search term is empty".into()));
   251	    }
   252	    if term.chars().count() > MAX_TERM {
   253	        return Err(VaultError::Invalid(format!("the search term is longer than {MAX_TERM} characters")));
   254	    }
   255	    Ok(format!("owner = {owner} AND title ~ \"{term}\""))
   256	}
   257	
   258	/// The ids of the documents in `store` that satisfy `filter`, in id order.
   259	pub fn run(store: &Store, filter: &str) -> Result<Vec<DocId>> {
   260	    let filter = parse(filter)?;
   261	    Ok(store.iter().filter(|d| filter.matches(d)).map(|d| d.id).collect())
   262	}
   263	
   264	/// The ids of the documents of `owner` whose title contains `term`.
   265	pub fn search(store: &Store, owner: UserId, term: &str) -> Result<Vec<DocId>> {
   266	    run(store, &search_filter(owner, term)?)
   267	}
