     9	
    10	/// The longest file name, in bytes.
    11	pub const MAX_PATH: usize = 200;
    12	
    13	/// The attachments under one base directory.
    14	#[derive(Debug, Clone)]
    15	pub struct FileRoot {
    16	    base: PathBuf,
    17	}
    18	
    19	impl FileRoot {
    20	    /// Attachments live under `base`.
    21	    pub fn new(base: impl Into<PathBuf>) -> FileRoot {
    22	        FileRoot { base: base.into() }
    23	    }
    24	
    25	    /// The base directory.
    26	    pub fn base(&self) -> &Path {
    27	        &self.base
    28	    }
    29	
    30	    /// Where the attachment called `name` lives. Names may hold sub-folders (`notes/a.txt`).
    31	    pub fn resolve(&self, name: &str) -> Result<PathBuf> {
    32	        let name = name.trim();
    33	        if name.is_empty() {
    34	            return Err(VaultError::Invalid("the file name is empty".into()));
    35	        }
    36	        if name.len() > MAX_PATH || name.contains('\0') {
    37	            return Err(VaultError::Invalid("the file name is not acceptable".into()));
    38	        }
    39	        Ok(self.base.join(name))
    40	    }
    41	
    42	    /// The content of an attachment.
    43	    pub fn read(&self, name: &str) -> Result<Vec<u8>> {
    44	        let path = self.resolve(name)?;
    45	        let bytes = std::fs::read(&path)?;
    46	        if bytes.len() > MAX_FILE {
    47	            return Err(VaultError::Invalid(format!("{name} is larger than {MAX_FILE} bytes")));
    48	        }
    49	        Ok(bytes)
    50	    }
