    52	    /// Stores an attachment, creating its sub-folders, and replaces any earlier one.
    53	    pub fn write(&self, name: &str, content: &[u8]) -> Result<()> {
    54	        if content.len() > MAX_FILE {
    55	            return Err(VaultError::Invalid(format!("an attachment may have at most {MAX_FILE} bytes")));
    56	        }
    57	        let path = self.resolve(name)?;
    58	        if let Some(dir) = path.parent() {
    59	            std::fs::create_dir_all(dir)?;
    60	        }
    61	        std::fs::write(&path, content)?;
    62	        Ok(())
    63	    }
    64	
    65	    /// Deletes an attachment.
    66	    pub fn remove(&self, name: &str) -> Result<()> {
    67	        std::fs::remove_file(self.resolve(name)?)?;
    68	        Ok(())
    69	    }
    70	
    71	    /// Whether an attachment with this name exists.
    72	    pub fn exists(&self, name: &str) -> bool {
    73	        self.resolve(name).map(|p| p.is_file()).unwrap_or(false)
    74	    }
    75	
    76	    /// The names of all attachments, sorted, with `/` between folders.
    77	    pub fn list(&self) -> Result<Vec<String>> {
    78	        let mut out = Vec::new();
    79	        if self.base.is_dir() {
    80	            collect(&self.base, "", &mut out)?;
    81	        }
    82	        out.sort();
    83	        Ok(out)
    84	    }
