    86	
    87	fn collect(dir: &Path, prefix: &str, out: &mut Vec<String>) -> Result<()> {
    88	    for entry in std::fs::read_dir(dir)? {
    89	        let entry = entry?;
    90	        let name = format!("{prefix}{}", entry.file_name().to_string_lossy());
    91	        if entry.file_type()?.is_dir() {
    92	            collect(&entry.path(), &format!("{name}/"), out)?;
    93	        } else {
    94	            out.push(name);
    95	        }
    96	    }
    97	    Ok(())
    98	}

