    10	/// The formats a document can be exported in.
    11	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
    12	pub enum Format {
    13	    Text,
    14	    Markdown,
    15	    Json,
    16	}
    17	
    18	impl Format {
    19	    /// The format called `s` (`txt`, `md` or `json`).
    20	    pub fn parse(s: &str) -> Result<Format> {
    21	        match s.trim().to_ascii_lowercase().as_str() {
    22	            "txt" | "text" => Ok(Format::Text),
    23	            "md" | "markdown" => Ok(Format::Markdown),
    24	            "json" => Ok(Format::Json),
    25	            other => Err(VaultError::Invalid(format!("unknown export format {other:?}"))),
    26	        }
    27	    }
    28	
    29	    /// The file extension of the format.
    30	    pub fn extension(self) -> &'static str {
    31	        match self {
    32	            Format::Text => "txt",
    33	            Format::Markdown => "md",
    34	            Format::Json => "json",
    35	        }
    36	    }
    37	}
    38	
    39	/// `s` as a JSON string, quotes included.
    40	pub fn json_string(s: &str) -> String {
    41	    let mut out = String::from("\"");
    42	    for c in s.chars() {
    43	        match c {
    44	            '"' => out.push_str("\\\""),
    45	            '\\' => out.push_str("\\\\"),
    46	            '\n' => out.push_str("\\n"),
    47	            '\r' => out.push_str("\\r"),
    48	            '\t' => out.push_str("\\t"),
    49	            c if c.is_control() => out.push_str(&format!("\\u{:04x}", c as u32)),
    50	            c => out.push(c),
    51	        }
    52	    }
    53	    out.push('"');
    54	    out
    55	}
    56	
    57	/// The document in the given format.
    58	pub fn render(doc: &Document, format: Format) -> String {
    59	    match format {
    60	        Format::Text => format!("{}\n\n{}\n", doc.title, doc.body),
    61	        Format::Markdown => {
    62	            let tags: Vec<String> = doc.tags.iter().map(|t| format!("`{t}`")).collect();
    63	            format!("# {}\n\n{}\n\n{}\n", doc.title, doc.body, tags.join(" "))
    64	        }
    65	        Format::Json => {
    66	            let tags: Vec<String> = doc.tags.iter().map(|t| json_string(t)).collect();
    67	            format!(
    68	                "{{\"id\":{},\"owner\":{},\"title\":{},\"body\":{},\"tags\":[{}]}}",
    69	                doc.id,
    70	                doc.owner,
    71	                json_string(&doc.title),
    72	                json_string(&doc.body),
    73	                tags.join(",")
    74	            )
    75	        }
    76	    }
    77	}
    78	
    79	/// The file a document titled `title` is exported to under `base`.
    80	pub fn export_path(base: &Path, title: &str, format: Format) -> PathBuf {
    81	    base.join(format!("{}.{}", sanitize_name(title), format.extension()))
    82	}
    83	
    84	/// Every document of `owner` as `(file, content)`. Two titles that give the same file name get
    85	/// the document id added, so no export overwrites another.
    86	pub fn export_all(store: &Store, owner: UserId, base: &Path, format: Format) -> Vec<(PathBuf, String)> {
    87	    let mut out: Vec<(PathBuf, String)> = Vec::new();
    88	    for doc in store.by_owner(owner) {
    89	        let mut path = export_path(base, &doc.title, format);
    90	        if out.iter().any(|(p, _)| *p == path) {
    91	            path = export_path(base, &format!("{} {}", doc.title, doc.id), format);
    92	        }
    93	        out.push((path, render(doc, format)));
    94	    }
    95	    out
    96	}
