     1	//! The binary frames a front end sends: a ten-byte header, a payload and a one-byte checksum.
     2	//!
     3	//! ```text
     4	//! offset 0   4 bytes  magic "VLT1"
     5	//! offset 4   1 byte   kind (1 ping, 2 put, 3 get, 4 delete)
     6	//! offset 5   1 byte   flags (unused, kept for later)
     7	//! offset 6   4 bytes  payload length, big endian
     8	//! offset 10  n bytes  payload
     9	//! offset 10+n 1 byte  checksum: the payload bytes added up modulo 256
    10	//! ```
    11	
    12	use crate::error::{Result, VaultError};
    13	
    14	/// The first four bytes of every frame.
    15	pub const MAGIC: [u8; 4] = *b"VLT1";
    16	
    17	/// The bytes before the payload.
    18	pub const HEADER_LEN: usize = 10;
    19	
    20	/// The largest payload a frame may carry.
    21	pub const MAX_PAYLOAD: usize = 1 << 20;
    22	
    23	/// What a frame asks for.
    24	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
    25	pub enum Kind {
    26	    Ping,
    27	    Put,
    28	    Get,
    29	    Delete,
    30	}
    31	
    32	impl Kind {
    33	    fn from_byte(b: u8) -> Result<Kind> {
    34	        match b {
    35	            1 => Ok(Kind::Ping),
    36	            2 => Ok(Kind::Put),
    37	            3 => Ok(Kind::Get),
    38	            4 => Ok(Kind::Delete),
    39	            other => Err(VaultError::Malformed(format!("unknown frame kind {other}"))),
    40	        }
    41	    }
    42	
    43	    fn byte(self) -> u8 {
    44	        match self {
    45	            Kind::Ping => 1,
    46	            Kind::Put => 2,
    47	            Kind::Get => 3,
    48	            Kind::Delete => 4,
    49	        }
    50	    }
    51	}
    52	
    53	/// One decoded frame.
    54	#[derive(Debug, Clone, PartialEq, Eq)]
    55	pub struct Frame {
    56	    pub kind: Kind,
    57	    pub flags: u8,
    58	    pub payload: Vec<u8>,
    59	}
    60	
    61	/// The checksum of a payload.
    62	pub fn checksum(payload: &[u8]) -> u8 {
    63	    payload.iter().fold(0u8, |acc, b| acc.wrapping_add(*b))
    64	}
    65	
    66	impl Frame {
    67	    /// A frame with no flags.
    68	    pub fn new(kind: Kind, payload: Vec<u8>) -> Frame {
    69	        Frame { kind, flags: 0, payload }
    70	    }
    71	
    72	    /// The bytes of the frame.
    73	    pub fn encode(&self) -> Result<Vec<u8>> {
    74	        if self.payload.len() > MAX_PAYLOAD {
    75	            return Err(VaultError::Invalid(format!("a payload may have at most {MAX_PAYLOAD} bytes")));
    76	        }
    77	        let mut out = Vec::with_capacity(HEADER_LEN + self.payload.len() + 1);
    78	        out.extend_from_slice(&MAGIC);
    79	        out.push(self.kind.byte());
    80	        out.push(self.flags);
    81	        out.extend_from_slice(&(self.payload.len() as u32).to_be_bytes());
    82	        out.extend_from_slice(&self.payload);
    83	        out.push(checksum(&self.payload));
    84	        Ok(out)
    85	    }
    86	
    87	    /// Reads the first frame in `buf` and says how many bytes it took.
    88	    pub fn decode(buf: &[u8]) -> Result<(Frame, usize)> {
    89	        if buf.len() < HEADER_LEN {
    90	            return Err(VaultError::Malformed("the frame is shorter than its header".into()));
    91	        }
    92	        if buf[..4] != MAGIC {
    93	            return Err(VaultError::Malformed("bad magic".into()));
    94	        }
    95	        let kind = Kind::from_byte(buf[4])?;
    96	        let flags = buf[5];
    97	        let len = u32::from_be_bytes([buf[6], buf[7], buf[8], buf[9]]) as usize;
    98	        let end = HEADER_LEN + len;
    99	        let payload = buf[HEADER_LEN..end].to_vec();
   100	        if buf[end] != checksum(&payload) {
   101	            return Err(VaultError::Malformed("the checksum does not match".into()));
   102	        }
   103	        Ok((Frame { kind, flags, payload }, end + 1))
   104	    }
   105	
   106	    /// Every frame in `buf`, which must hold nothing else.
   107	    pub fn decode_all(buf: &[u8]) -> Result<Vec<Frame>> {
   108	        let mut frames = Vec::new();
   109	        let mut at = 0;
   110	        while at < buf.len() {
   111	            let (frame, used) = Frame::decode(&buf[at..])?;
   112	            frames.push(frame);
   113	            at += used;
   114	        }
   115	        Ok(frames)
   116	    }
   117	
   118	    /// The text command this frame stands for, as `Handler::handle` reads it.
   119	    pub fn to_line(&self) -> Result<String> {
   120	        match self.kind {
   121	            Kind::Ping => Ok("WHOAMI".to_string()),
   122	            Kind::Put => {
   123	                let (title, body) = parse_put(&self.payload)?;
   124	                if title.contains(['|', '\n', '\r']) {
   125	                    return Err(VaultError::Invalid("a title may not hold | or line breaks".into()));
   126	                }
   127	                Ok(format!("CREATE {title}|{body}|"))
   128	            }
   129	            Kind::Get | Kind::Delete => {
   130	                let id = parse_id(&self.payload)?;
   131	                let verb = if self.kind == Kind::Get { "GET" } else { "DELETE" };
   132	                Ok(format!("{verb} {id}"))
   133	            }
   134	        }
   135	    }
   136	}
   137	
   138	/// The payload of a put frame: a two-byte title length, the title, then the body.
   139	pub fn encode_put(title: &str, body: &str) -> Result<Vec<u8>> {
   140	    let len = u16::try_from(title.len()).map_err(|_| VaultError::Invalid("the title is too long".into()))?;
   141	    let mut out = len.to_be_bytes().to_vec();
   142	    out.extend_from_slice(title.as_bytes());
   143	    out.extend_from_slice(body.as_bytes());
   144	    Ok(out)
   145	}
   146	
   147	/// The title and body in a put payload.
   148	pub fn parse_put(payload: &[u8]) -> Result<(String, String)> {
   149	    let head = payload.get(..2).ok_or_else(|| VaultError::Malformed("the put payload has no title length".into()))?;
   150	    let title_len = usize::from(u16::from_be_bytes([head[0], head[1]]));
   151	    let title = payload
   152	        .get(2..2 + title_len)
   153	        .ok_or_else(|| VaultError::Malformed("the title is longer than the payload".into()))?;
   154	    let body = &payload[2 + title_len..];
   155	    let text =
   156	        |b: &[u8]| String::from_utf8(b.to_vec()).map_err(|_| VaultError::Invalid("the text is not UTF-8".into()));
   157	    Ok((text(title)?, text(body)?))
   158	}
   159	
   160	/// The document id in a get or delete payload: eight bytes, big endian.
   161	pub fn parse_id(payload: &[u8]) -> Result<u64> {
   162	    let bytes: [u8; 8] = payload
   163	        .try_into()
   164	        .map_err(|_| VaultError::Malformed(format!("an id payload has 8 bytes, not {}", payload.len())))?;
   165	    Ok(u64::from_be_bytes(bytes))
   166	}
