     1	//! The request handler: text commands in, status and text out. This is the layer a front end
     2	//! talks to; it checks the token, parses the command and calls the service.
     3	//!
     4	//! ```text
     5	//! LOGIN name password          -> a token
     6	//! WHOAMI                       -> the caller's name and role
     7	//! CREATE title|body|tag,tag    -> the new document id
     8	//! GET id | UPDATE id|body | DELETE id
     9	//! LIST | SEARCH term           -> one line per document
    10	//! EXPORT id format             -> the document as txt, md or json
    11	//! ATTACH name|content | FILE name
    12	//! ```
    13	
    14	use crate::auth;
    15	use crate::error::{Result, VaultError};
    16	use crate::export::{self, Format};
    17	use crate::files::FileRoot;
    18	use crate::service::Service;
    19	use crate::store::{DocId, Document};
    20	use crate::text::{escape_display, has_control, parse_tags, split_fields, truncate};
    21	use crate::wire::Frame;
    22	
    23	/// A status code and the text that goes with it.
    24	#[derive(Debug, Clone, PartialEq, Eq)]
    25	pub struct Response {
    26	    pub status: u16,
    27	    pub body: String,
    28	}
    29	
    30	impl Response {
    31	    fn ok(body: String) -> Response {
    32	        Response { status: 200, body }
    33	    }
    34	
    35	    fn from_error(e: &VaultError) -> Response {
    36	        Response { status: e.status(), body: e.message().to_string() }
    37	    }
    38	}
    39	
    40	/// The handler: a service, the secret its tokens are signed with, and the attachments folder.
    41	#[derive(Debug)]
    42	pub struct Handler {
    43	    service: Service,
    44	    secret: String,
    45	    files: FileRoot,
    46	}
    47	
    48	fn parse_id(s: &str) -> Result<DocId> {
    49	    s.trim().parse().map_err(|_| VaultError::Invalid(format!("{s:?} is not a document id")))
    50	}
    51	
    52	fn summary(doc: &Document) -> String {
    53	    format!("{}\t{}\t{} bytes", doc.id, escape_display(&truncate(&doc.title, 60)), doc.size())
    54	}
    55	
    56	impl Handler {
    57	    /// A handler over `service`, signing tokens with `secret`.
    58	    pub fn new(service: Service, secret: &str, files: FileRoot) -> Handler {
    59	        Handler { service, secret: secret.to_string(), files }
    60	    }
    61	
    62	    /// The service, for reading.
    63	    pub fn service(&self) -> &Service {
    64	        &self.service
    65	    }
    66	
    67	    /// The service, for setting things up.
    68	    pub fn service_mut(&mut self) -> &mut Service {
    69	        &mut self.service
    70	    }
    71	
    72	    /// Runs one command for the holder of `token` (`LOGIN` needs none).
    73	    pub fn handle(&mut self, token: &str, line: &str) -> Response {
    74	        match self.dispatch(token, line) {
    75	            Ok(body) => Response::ok(body),
    76	            Err(e) => Response::from_error(&e),
    77	        }
    78	    }
    79	
    80	    /// Runs the command a binary frame stands for.
    81	    pub fn handle_frame(&mut self, token: &str, bytes: &[u8]) -> Response {
    82	        let line = Frame::decode(bytes).and_then(|(frame, _)| frame.to_line());
    83	        match line {
    84	            Ok(line) => self.handle(token, &line),
    85	            Err(e) => Response::from_error(&e),
    86	        }
    87	    }
    88	
    89	    fn dispatch(&mut self, token: &str, line: &str) -> Result<String> {
    90	        if has_control(line) {
    91	            return Err(VaultError::Malformed("a command is one line".into()));
    92	        }
    93	        let line = line.trim();
    94	        let (verb, rest) = line.split_once(' ').unwrap_or((line, ""));
    95	        let verb = verb.to_ascii_uppercase();
    96	        if verb == "LOGIN" {
    97	            let mut words = rest.split_whitespace();
    98	            let (Some(name), Some(password)) = (words.next(), words.next()) else {
    99	                return Err(VaultError::Invalid("LOGIN needs a name and a password".into()));
   100	            };
   101	            return auth::login(&self.service.users, &self.secret, name, password);
   102	        }
   103	        let user = auth::verify_token(&self.service.users, &self.secret, token)?;
   104	        match verb.as_str() {
   105	            "WHOAMI" => {
   106	                let u = self.service.users.get(user).ok_or_else(|| VaultError::Unauthenticated("gone".into()))?;
   107	                Ok(format!("{} ({})", u.name, u.role.name()))
   108	            }
   109	            "CREATE" => {
   110	                let f = split_fields(rest, 3);
   111	                let id = self.service.create(user, f[0], f[1], parse_tags(f[2]))?;
   112	                Ok(format!("created {id}"))
   113	            }
   114	            "GET" => {
   115	                let doc = self.service.fetch(user, parse_id(rest)?)?;
   116	                Ok(format!("{}\n\n{}", doc.title, doc.body))
   117	            }
   118	            "UPDATE" => {
   119	                let f = split_fields(rest, 2);
   120	                let id = parse_id(f[0])?;
   121	                self.service.update(user, id, f[1])?;
   122	                Ok(format!("updated {id}"))
   123	            }
   124	            "DELETE" => {
   125	                let id = parse_id(rest)?;
   126	                self.service.delete(user, id)?;
   127	                Ok(format!("deleted {id}"))
   128	            }
   129	            "LIST" => Ok(self.service.list(user).into_iter().map(summary).collect::<Vec<_>>().join("\n")),
   130	            "SEARCH" => Ok(self.service.search(user, rest)?.into_iter().map(summary).collect::<Vec<_>>().join("\n")),
   131	            "EXPORT" => {
   132	                let f: Vec<&str> = rest.split_whitespace().collect();
   133	                let [id, format] = f[..] else {
   134	                    return Err(VaultError::Invalid("EXPORT needs an id and a format".into()));
   135	                };
   136	                let doc = self.service.fetch(user, parse_id(id)?)?;
   137	                Ok(export::render(doc, Format::parse(format)?))
   138	            }
   139	            "ATTACH" => {
   140	                let role = self.service.users.role_of(user);
   141	                if !role.is_some_and(|r| r.can_write()) {
   142	                    return Err(VaultError::Denied("guests cannot attach files".into()));
   143	                }
   144	                let f = split_fields(rest, 2);
   145	                self.files.write(f[0], f[1].as_bytes())?;
   146	                Ok(format!("stored {}", f[0]))
   147	            }
   148	            "FILE" => Ok(String::from_utf8_lossy(&self.files.read(rest)?).into_owned()),
   149	            _ => Err(VaultError::Invalid(format!("unknown command {verb:?}"))),
   150	        }
   151	    }
   152	}

